from google import genai
from google.genai import types

from config import GEMINI_API_KEY, MODEL
from prompt import INTERNET_SEARCH_PROMPT
import json
import database


client = genai.Client(api_key=GEMINI_API_KEY)

def search_internet(transcript_dict: dict):
    prompt = INTERNET_SEARCH_PROMPT.format(subject=transcript_dict['subject'], topic=transcript_dict['topics'])
    response = client.models.generate_content(
                model=MODEL,
                contents=prompt,
                config=types.GenerateContentConfig(
        response_mime_type="application/json"
            )
        )
    print(type(response.text))

    result= (json.loads(response.text.strip()))
    print(result)

    #storing in database 
    database.store_transcript(transcript_dict['video_id'], transcript_dict['text'], transcript_dict['video_meta_data'])
    database.store_topics(transcript_dict['video_id'], transcript_dict['subject'], transcript_dict['topics'])
    database.store_questions(result)
  
    
    return result

